entries[74723] = { ["name"] = "Waffe - Windweise", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilzauber, Schadenszauber und Schaden verursachenden Nahkampfangriffe manchmal Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert 12 Sek. lang um 1500 erhöhen.\nVerkaufspreis:" }
entries[74724] = { ["name"] = "Waffe - Jadegeist", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 1650 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Willenskraft ebenfalls um 0 erhöht.\nVerkaufspreis:" }
entries[74725] = { ["name"] = "Waffe - Elementarkraft", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe und Zauber manchmal zusätzliche 3000 Elementarschaden verursachen.\nVerkaufspreis:" }
entries[74726] = { ["name"] = "Waffe - Tanzender Stahl", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Eure Stärke oder Beweglichkeit um 1650 erhöhen. Der höhere der beiden Werte wird gewählt.\nVerkaufspreis:" }
entries[74727] = { ["name"] = "Waffe - Koloss", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal einen Schutzzauber der Mogu auslösen, der bis zu 7500 erlittenen Schaden absorbiert.\nVerkaufspreis:" }
entries[74728] = { ["name"] = "Waffe - Flussgesang", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Euer Ausweichen 7 Sek. lang um 1650 erhöhen.\nVerkaufspreis:" }
entries[74729] = { ["name"] = "Schildhand - Erhebliche Intelligenz", ["text"] = "Benutzen: Einen Gegenstand für die Schildhand dauerhaft verzaubern, sodass die Intelligenz um 165 erhöht wird.\nVerkaufspreis:" }
entries[74748] = { ["name"] = "Aufgeladener Entschlüsselungsring", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entschlüsselt die angesengte Chiffre.\n\"Vollständig mit arkaner Energie aufgeladen.\"" }
entries[74749] = { ["name"] = "Aufladender Entschlüsselungsring", ["text"] = "Questgegenstand\nEinzigartig\nDauer: 12 std. (Realzeit)\n\"Ein leichtes Glühen zeigt an, dass der Ring sich gerade auflädt.\"" }
entries[74750] = { ["name"] = "Angesengte Geheimnachricht", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Runen, aus der diese Geheimnachricht besteht, scheinen sich ständig zu verändern.\"" }
entries[74752] = { ["name"] = "Gelöste Geheimnachricht", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine entschlüsselte Nachricht von den Schurken, die den roten Drachenschwarm infiltriert haben!\"\n<Zum Lesen rechtsklicken>" }
entries[74755] = { ["name"] = "König Dreds Zahn", ["text"] = "Questgegenstand\n\"Dieser gewaltige Zahn würde ohne weiteres eine passable Waffe abgeben.\"" }
entries[74760] = { ["name"] = "Gesprungene Ritualschale", ["text"] = "Questgegenstand\n\"Konzentrische Kreise verzieren die Innenseite der ansonsten unscheinbaren Lehmschale.\"" }
entries[74761] = { ["name"] = "Geruchsintensive Ritualkerze", ["text"] = "Questgegenstand\n\"Räucherwerk, zerstoßene Kräuter und Mineralstaub wurden in das Wachs eingearbeitet, wodurch ein kräftiger Duft und eine helle Flamme entsteht.\"" }
entries[74762] = { ["name"] = "Jadecong", ["text"] = "Questgegenstand\n\"Ein quadratischer Zylinder mit aufwendigen Schnitzereien auf jeder Seite.\"" }
entries[74763] = { ["name"] = "Geisterflasche", ["text"] = "Questgegenstand\n\"Eine Gravur auf der Flasche besagt: 'Der Körper ist nur ein Gefäß. Die Klaue sucht, was sich in ihm versteckt.'\"" }
entries[74768] = { ["name"] = "Unlesbare Schriftrolle", ["text"] = "Wird beim Aufheben gebunden\n\"Fremdartige Markierungen bilden auf diesem Pergament ein hypnotisierendes Muster.\"" }
entries[74770] = { ["name"] = "Händlerpetition", ["text"] = "Questgegenstand\n\"Eine Liste der Beschwerden von wütenden Händlern, die aufgebracht sind über die Unterbrechung der Handelsrouten nach Kalimdor.\"" }
entries[74771] = { ["name"] = "Stab von Pei-Zhi", ["text"] = "Questgegenstand\nBenutzen: Zieht einen verirrten Urahnen in den Stab. Kann sich während der Kanalisierung bewegen." }
entries[74776] = { ["name"] = "Hicks' Hammer", ["text"] = "Einhändig Streitkolben\n3 - 7 Schaden Tempo 2.70\n(1.85 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nVerkaufspreis:" }
entries[74783] = { ["name"] = "Eroberungsrelikt des kataklysmischen Gladiators", ["text"] = "Saison 11, Elite\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[74784] = { ["name"] = "Erretterrelikt des kataklysmischen Gladiators", ["text"] = "Saison 11, Elite\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[74785] = { ["name"] = "Vorherrschaftsrelikt des kataklysmischen Gladiators", ["text"] = "Saison 11, Elite\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[74786] = { ["name"] = "Triumphales Relikt des kataklysmischen Gladiators", ["text"] = "Saison 11, Elite\nWird beim Aufheben gebunden\nVerkaufspreis:" }
entries[74808] = { ["name"] = "Geisterflasche", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Geisterflasche, um sie zu zerschmettern und den Geist im Inneren zu befreien. (6 Sek. Abklingzeit)" }
entries[74812] = { ["name"] = "Verdünntes Kalziumoxidsulfur", ["text"] = "Questgegenstand\n\"Eine giftige Lösung, die sowohl Eure Freunde vertreibt als auch alles tötet, was in Euren Haaren lebt.\"\nVerkaufspreis:" }
entries[74813] = { ["name"] = "Hartriegelextrakt", ["text"] = "Questgegenstand\n\"Ein Extrakt des Hartriegelstrauchs, mit dem Tiere gewaschen werden, die von der Krätze befallen sind.\"\nVerkaufspreis:" }
entries[74815] = { ["name"] = "Beruhigendes Shampoo", ["text"] = "Questgegenstand\n\"Mit der speziellen Formel zur Beruhigung von empfindlicher und gereizter Haut.\"\nVerkaufspreis:" }
entries[74822] = { ["name"] = "Sarsaparilla-Bombe", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt ( 16000 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Eine sprudelnde Sarsaparilla mit Vanilleeiskugeln.\"\nVerkaufspreis:" }
entries[74830] = { ["name"] = "Kristallene Träne der Trauer", ["text"] = "Questgegenstand\n\"Wenn Ihr diesen Kristall in den Händen haltet, durchfließen Euch Erinnerungen aller traurigen Momente Eures Lebens.\"" }
