entries[74872] = { ["name"] = "Übles Gebräu", ["text"] = "Questgegenstand\nBenutzen: Bedeckt das Ziel mit einem üblen Gebräu. (1 Min Abklingzeit)\n\"Der Geschmack brennt, buchstäblich.\"" }
entries[74918] = { ["name"] = "Problemlösungsanhänger", ["text"] = "Hals\n\"Kein Geld, keine Probleme.\"\nVerkaufspreis:" }
entries[74919] = { ["name"] = "Pandarenfestmahl", ["text"] = "Benötigt Stufe 90\nBenutzen: Richtet ein Pandarenfestmahl her, das bis zu 10 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\nVerkaufspreis:" }
entries[74921] = { ["name"] = "Dunkelmond-Donut", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 96000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[74925] = { ["name"] = "Meditationskerze", ["text"] = "Questgegenstand\nBenötigt Stufe 85\n\"Die Kerze brennt hell, aber die Flamme gibt keinen Rauch ab.\"" }
entries[74955] = { ["name"] = "Sprengsatz", ["text"] = "Questgegenstand\n\"Dieses Ende anzünden.\"" }
entries[74958] = { ["name"] = "Medizinische Versorgungsgüter der Allianz", ["text"] = "Questgegenstand\n\"Im Verletzungsfall hier aufbrechen.\"" }
entries[74981] = { ["name"] = "Dunkelmond-Junges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Dunkelmond-Junges beschwören oder wieder freigeben." }
entries[74999] = { ["name"] = "Spiegel der wahren Sicht", ["text"] = "Questgegenstand\nBenutzen: Stellt mithilfe des Spiegels fest, ob ein verdächtiger Bürger wirklich ein gegnerischer Spion ist.\n\"Ein Artefakt, von dem man sagt, dass es die Wahrheit über die Dinge enthüllt, die sich in ihm spiegeln.\"" }
entries[75000] = { ["name"] = "Fackel der Prismatischen Flamme", ["text"] = "Die Wandernde Insel\nQuestgegenstand\nEinzigartig\n\"Die lodernde Flamme vermittelt Euch ein Gefühl der Stärke und der Sicherheit.\"" }
entries[75008] = { ["name"] = "Unangezündete Herausfordererfackel", ["text"] = "Questgegenstand\nEinzigartig\n\"Wisst Ihr, was dieser Fackel wirklich gut stehen würde? Feuer.\"" }
entries[75013] = { ["name"] = "Rezept: Pandarenfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (600)\nBenutzen: Lehrt Euch, wie man ein Pandarenfestmahl zubereitet.\nVerkaufspreis:\nPandarenfestmahl\nBenötigt Stufe 90\nBenutzen: Richtet ein Pandarenfestmahl her, das bis zu 10 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\nVerkaufspreis:\nBenötigt Hundert Jahre alte Sojasoße , Juwelendanio (10), Rohes Tigersteak (10), Rosa Rübe (50)" }
entries[75014] = { ["name"] = "Roher Krokiliskenbauch", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[75015] = { ["name"] = "Sirloin-Steak", ["text"] = "\"Wird beim Kochen verwendet.\"\nVerkaufspreis:" }
entries[75016] = { ["name"] = "Großes Pandarenfestmahl", ["text"] = "Benötigt Stufe 90\nBenutzen: Richtet ein großes Pandarenfestmahl her, das bis zu 25 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\nVerkaufspreis:" }
entries[75017] = { ["name"] = "Rezept: Großes Pandarenfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (600)\nBenutzen: Lehrt Euch, wie man ein großes Pandarenfestmahl zubereitet.\nVerkaufspreis:\nGroßes Pandarenfestmahl\nBenötigt Stufe 90\nBenutzen: Richtet ein großes Pandarenfestmahl her, das bis zu 25 Leute in Eurem Schlachtzug oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\nVerkaufspreis:\nBenötigt Hundert Jahre alte Sojasoße , Juwelendanio (20), Rohes Tigersteak (20), Rosa Rübe (100)" }
entries[75023] = { ["name"] = "Makelloser Seidenstrang", ["text"] = "Questgegenstand\n\"Selbst das Licht scheut sich, auf diesem Seidenstrang zu verweilen.\"" }
entries[75026] = { ["name"] = "Ginsengtee", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt im Verlauf von 20 Sek. 199999 Gesundheit und ( 50000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[75027] = { ["name"] = "Teldrassil-Filet", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Aber SICHER ist es Wildbret, Schätzchen. Was sollte es SONST sein?!\"" }
entries[75028] = { ["name"] = "Sturmwind-Surprise", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 2% Eures Manas wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Hee! Heeheehee! Heee-he- *örks* *hust* Ahem. Hee!\"" }
entries[75029] = { ["name"] = "Biergetränkte Rippchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Die Haare da dran sind von der Speckschwarte, heehee.\"" }
entries[75030] = { ["name"] = "Gnomeregan-Gnuggets", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Paniert, mundgerecht und industrialisiert. Äh, ich meinte industriell hergestellt.\"" }
entries[75031] = { ["name"] = "Draeneiklößchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Mit handverlesenen Eiern. Oder - halt nein, doch Fleisch. Heehee!\"" }
entries[75032] = { ["name"] = "Mulgore-Fleischküchlein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Da kommt einfach das BESTE Fleisch her, Schätzchen. Hee!\"" }
entries[75033] = { ["name"] = "Grüner Speck und Eier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Bester Speck von diesen widerborstigen, zähen Durotar-Schweinen, heehee! Und Möweneier.\"" }
entries[75034] = { ["name"] = "Foie Gras à la Unterstadt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Aber SICHER gibt es Enten und Gänse in Tirisfal, Schätzchen.\"" }
entries[75035] = { ["name"] = "Trolltatar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Tatar nach TROLLART, nicht wahr, Schätzchen. Heehee!\"" }
entries[75036] = { ["name"] = "Silbermondsteak", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Stellt im Verlauf von 25 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Mager und zart, von den BESTEN Weiden des Immersangwalds!\"" }
