entries[76062] = { ["name"] = "Speer des Fetischschamanen", ["text"] = "Accountgebunden\nBenutzen: Lehrt Euch, wie man einen Fetischschamanen beschwört.\nMit Rechtsklick Euren Fetischschamanen beschwören oder wieder freigeben." }
entries[76075] = { ["name"] = "Elixier der Mantis", ["text"] = "Benötigt Stufe 85\nBenutzen: Erhöht die Rüstung 1 Stunde lang um 2250 . Wächterelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
