entries[76091] = { ["name"] = "Großer Trank des Glücks", ["text"] = "Benötigt Stufe 85\nBenutzen: Gestattet es Euch, manchmal zusätzliche Beute von Monstern in Pandaria zu bekommen. Hält 1 Stunde lang an. Dieser Effekt hält über den Tod hinaus an. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[76092] = { ["name"] = "Trank des Fokus", ["text"] = "Benötigt Stufe 85\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in welchem er im Verlauf von 10 Sek. bis zu ( 4500 * 10) Mana regeneriert, jedoch verteidigungslos ist, bis die Konzentration gebrochen wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
