entries[76167] = { ["name"] = "Traumgebräu", ["text"] = "Questgegenstand\nBenutzen: Trinkt das Traumgebräu, um eine Vision der Vergangenheit zu erfahren. (30 Sek. Abklingzeit)\n\"Dieses seltene und geheimnisvolle Gebräu vermag es, den Geist und den Verstand zu erweitern und so Sterblichen dabei zu helfen, Antworten auf ihre innersten Fragen zu erhalten.\"" }
